update pages set contenu = '{"gabarit":"fiche","chapeau":"VALEO, leader mondial des technologies de pointe pour l''automobile, a choisi Migen en septembre 2024. L''objectif : accompagner la montée en cadence de plusieurs de ses usines en France.","fiche":[],"contexte":"**Monter en cadence sans renforcer la maintenance revient à accélérer avec des freins usés.** L''équipe encaisse la hausse avec le même effectif, jusqu''au jour où elle ne l''encaisse plus.\nPlusieurs usines françaises devaient passer à des niveaux de production plus élevés. Les enjeux du dossier :\n**Une transition fluide vers des cadences supérieures**, sans décrochage de la production.\n**Un standard de performance et de sécurité maintenu** pendant l''accélération.\n**Des interruptions non planifiées réduites** sur les équipements industriels.\n**Une disponibilité optimisée** dans plusieurs usines à la fois.","intervention":"**Des techniciens là où la charge monte** : Trois à cinq techniciens hautement qualifiés déployés au sein de différents services des usines concernées.\n**Une couverture sur trois fronts** : Lignes de production, ateliers de fabrication et services de maintenance préventive, dans le même dispositif.\n**Anticipation des défaillances** : Le suivi technique vise à repérer la dérive avant l''arrêt, pas à réparer après coup.\n**Intervention rapide sur panne** : La présence sur site limite les temps d''arrêt quand l''incident survient.\nLa mission principale : assurer un suivi technique rigoureux, anticiper les défaillances et intervenir vite pour limiter les temps d''arrêt.","resultats":[]}'::jsonb where path = '/preuves/valeo-usines/';
update pages set contenu = jsonb_set(contenu, '{fiche}', (contenu->'fiche') || '[{"libelle":"Client","valeur":"VALEO"},{"libelle":"Territoire","valeur":"Plusieurs usines en France"},{"libelle":"Secteur","valeur":"Industrie automobile, véhicules électriques et connectés"},{"libelle":"Démarrage","valeur":"Septembre 2024, mission en cours"},{"libelle":"Effectif Migen","valeur":"3 à 5 techniciens de maintenance"},{"libelle":"Durée","valeur":"Moyen terme"},{"libelle":"Fréquence","valeur":"Permanente"},{"libelle":"Périmètre","valeur":"Lignes de production, ateliers de fabrication, maintenance préventive"}]'::jsonb) where path = '/preuves/valeo-usines/';
update pages set contenu = jsonb_set(contenu, '{resultats}', (contenu->'resultats') || '[{"valeur":"Une qualité de production constante","libelle":"Le niveau est maintenu pendant l''accélération des cadences."},{"valeur":"Un accompagnement flexible et réactif","libelle":"Il s''ajuste aux besoins de chaque service."},{"valeur":"Des capacités industrielles renforcées","libelle":"Sans recrutement interne mené dans l''urgence."}]'::jsonb) where path = '/preuves/valeo-usines/';
